SELECT COUNT(1)
FROM room_category
WHERE camp_id = #{campId}
  AND room_category_id = #{roomCategoryId}
  AND status = 1
  AND is_deleted = 0

SELECT COALESCE(MAX(sort_no), 0) + 1
FROM room_category_media
WHERE camp_id = #{campId}
  AND room_category_id = #{roomCategoryId}
  AND scene_type = #{sceneType}
  AND status = 1
